head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gLastJob = "";
// 화면 리사이징

// 자료수정 시 부모창으로부터 넘어온 데이터
scwin.key_edu_partc_id = frame.opener.scwin.key_edu_partc_id; // PK
scwin.key_isur_cd = frame.opener.scwin.key_isur_cd; // 회사코드
scwin.key_chrg_tp_cd = frame.opener.scwin.key_chrg_tp_cd; // 담당자구분코드
scwin.key_edu_id = frame.opener.scwin.key_edu_id; // 교육일정코드
scwin.key_chrg_nm = frame.opener.scwin.key_chrg_nm; // 선택된참가자명
scwin.key_edu_nm = frame.opener.scwin.key_edu_nm; // 선택과정명
scwin.key_edu_ack_tm = frame.opener.scwin.key_edu_ack_tm;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        $c.cm.PanelToGroupBox(panel_2);
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        scwin.init();
        await scwin.setHeader();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30627.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

// 이수시간

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    const ToDay = new Date();
    const yyyy = parseInt(ToDay.getYear(), 10);
    let str = "^전체";
    for (let i = yyyy; i >= 2010; i--) {
        str += "," + i + "%^" + i;
    }

    // 값 초기화
    tbx_COM_NM.setValue("");
    tbx_CHRG_TP_NM.setValue("");
    tbx_CHRG_NM.setValue("");
    tbx_hidden_chrg_tp_cd.setValue("");
    tbx_ASIS_DUTY_EDU_TM.setValue("");
    tbx_ASIS_EDU_ACK_TM.setValue("");
    tbx_TOBE_DUTY_EDU_TM.setValue("");
    tbx_TOBE_EDU_ACK_TM.setValue("");
    tbx_hidden_DISCLS_BZ_CHRG_ASSGN_DD.setValue("");
    tbx_hidden_chrg_tp_cd.hide();
    tbx_hidden_DISCLS_BZ_CHRG_ASSGN_DD.hide();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_ComDisclsPerson_OnFail
 * @description Com Discls Person On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ComDisclsPerson_OnFail = async function() {
    try {
        await $c.win.alert(dts_ComDisclsPerson);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30627.dts_ComDisclsPerson_OnFail" });
    }
};

/**
 * @method
 * @name dts_ComDisclsPerson_OnLoadError
 * @description dts_ComDisclsPerson 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ComDisclsPerson_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_ComDisclsPerson);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30627.dts_ComDisclsPerson_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_ComDisclsPerson_OnLoadCompleted
 * @description dts_ComDisclsPerson 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ComDisclsPerson_OnLoadCompleted = function(rowcount) {
    try {
        if (rowcount <= 0) {
            dts_ComDisclsPerson.removeAll();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30627.dts_ComDisclsPerson_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30627.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30627.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30627.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30627.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30627.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30627.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30627.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30627.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30627.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30627.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name grd_Grid_OnClick
 * @description grd_Grid 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnClick = async function(row, colid) {
    try {
        // 선택값 셋팅
        const CHAR_NM = dts_ComDisclsPerson.getCellData(row, "CHRG_NM"); // 담당자명
        const COM_ABBRV = dts_ComDisclsPerson.getCellData(row, "COM_ABBRV"); // 회사명
        const EDU_KIND_NM = dts_ComDisclsPerson.getCellData(row, "EDU_KIND_NM"); // 담당자구분
        const CHRG_TP_CD = dts_ComDisclsPerson.getCellData(row, "CHRG_TP_CD"); // 담당자구분코드
        const DISCLS_BZ_CHRG_ASSGN_DD = dts_ComDisclsPerson.getCellData(row, "DISCLS_BZ_CHRG_ASSGN_DD"); // 담당자지정일

        tbx_COM_NM.setValue(COM_ABBRV);
        tbx_CHRG_TP_NM.setValue(EDU_KIND_NM);
        tbx_CHRG_NM.setValue(CHAR_NM);
        tbx_hidden_chrg_tp_cd.setValue(CHRG_TP_CD);
        tbx_hidden_DISCLS_BZ_CHRG_ASSGN_DD.setValue(DISCLS_BZ_CHRG_ASSGN_DD);

        // 두번째 그리드 조회(변경이력 내역 조회)
        const ISUR_CD = dts_ComDisclsPerson.getCellData(row, "ISUR_CD"); // 회사코드
        await scwin.search2(ISUR_CD, CHAR_NM, CHRG_TP_CD);

        // '교육참가이력 변경적용 시물레이션 결과' 값 셋팅
        tbx_ASIS_DUTY_EDU_TM.setValue(dts_ComDisclsPerson.getCellData(row, "DUTY_EDU_TM")); // 교육의무시간(변경전)
        tbx_ASIS_EDU_ACK_TM.setValue(dts_ComDisclsPerson.getCellData(row, "EDU_ACK_TM")); // 이수시간(변경전)
        tbx_TOBE_DUTY_EDU_TM.setValue(dts_ComDisclsPerson.getCellData(row, "DUTY_EDU_TM")); // 교육의무시간(변경후)
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30627.grd_Grid_OnClick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = function(row, colid) {

};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30627.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name txb_chrg_nm_onkeypress
 * @description txb_chrg_nm onkeypress 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_chrg_nm_onkeypress = async function() {
    try {
        await scwin.search(); // 엔터키 입력시 조회 수행
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30627.txb_chrg_nm_onkeypress" });
    }
};

/**
 * @method
 * @name dts_Edu_Plan_OnFail
 * @description Edu Plan On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Edu_Plan_OnFail = async function() {
    try {
        await $c.win.alert(dts_Edu_Plan);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30627.dts_Edu_Plan_OnFail" });
    }
};

/**
 * @method
 * @name dts_Edu_Plan_OnLoadError
 * @description dts_Edu_Plan 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Edu_Plan_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Edu_Plan);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30627.dts_Edu_Plan_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Edu_Plan_OnLoadCompleted
 * @description dts_Edu_Plan 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Edu_Plan_OnLoadCompleted = function(rowcount) {
    try {
        if (rowcount <= 0) {
            dts_Edu_Plan.removeAll();
            tbx_TOBE_DUTY_EDU_TM.setValue("");
            tbx_TOBE_EDU_ACK_TM.setValue("");
        } else {
            // 변경후 이수시간 계산 및 값 입력
            let EDU_ACK_TM_SUM = 0;
            for (let i = 1; i <= rowcount; i++) {
                EDU_ACK_TM_SUM = parseInt(EDU_ACK_TM_SUM) + parseInt(dts_Edu_Plan.getCellData(i, "EDU_ACK_TM"));
            }
            tbx_TOBE_EDU_ACK_TM.setValue(EDU_ACK_TM_SUM); // 이수시간(변경후)

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30627.dts_Edu_Plan_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30627.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30627.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert("Error Code : " + trs_Save.ErrorCode + "\n" + "Error Message : " + trs_Save.ErrorMsg + "\n");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30627.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        const msg = $c.stf.getMessageParam("MSG-A001", scwin.gLastJob);
        await $c.win.alert(msg);
        const fr_fn_Search = $c.frame.path("../").fn_Search;
        fr_fn_Search();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30627.trs_Save_OnSuccess" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 담당자 검색
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&ISUR_CD=" + txb_isur_cd.getValue();
    url += "&CHRG_NM=" + txb_chrg_nm.getValue();
    url += "&SCREN_ID=" + "ULDSTF30627.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_ComDisclsPerson",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_ComDisclsPerson=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

// 선택한 담당자에 대한 이력변경 대상 목록 조회(회사코드, 담당자명, 담당자구분코드)

/**
 * @method
 * @name search2
 * @description search2 처리
 * @param {*} p_isur_cd p_isur_cd
 * @param {*} p_chrg_nm p_chrg_nm
 * @param {*} p_chrg_tp_cd p_chrg_tp_cd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search2 = async function(p_isur_cd, p_chrg_nm, p_chrg_tp_cd) {
    url += "&ISUR_CD=" + p_isur_cd;
    url += "&CHRG_NM=" + p_chrg_nm;
    url += "&CHRG_TP_CD=" + p_chrg_tp_cd;
    url += "&SCREN_ID=" + "ULDSTF30627.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Edu_Plan",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Edu_Plan=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setHeader
 * @description set Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_Save",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name save
 * @description 저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (tbx_COM_NM.getValue() === '' || tbx_hidden_chrg_tp_cd.getValue() === '') {
        await $c.win.alert('이력변경 대상자를 선택하시기 바랍니다.');
        return;
    }
    if (dts_Edu_Plan.getRowCount() === 0) {
        await $c.win.alert('변경가능한 교육참가이력이 없습니다.');
        return;
    }
    if (confirm('저장 하시겠습니까?')) {
        scwin.gLastJob = "저장";
        dts_Save.setBroadcast(false);
        for (let i = 1; i <= dts_Edu_Plan.getRowCount(); i++) {
            dts_Save.insertRow();
            dts_Save.setCellData(i, "EDU_PARTC_ID", dts_Edu_Plan.getCellData(i, "EDU_PARTC_ID"));
        }
        dts_Save.setBroadcast(true, true);
        let url = "/ListedCompany.do?method=saveDisclsEduPartcHistory";
        url += "&CHRG_TP_CD=" + tbx_hidden_chrg_tp_cd.getValue();
        url += "&DISCLS_BZ_CHRG_ASSGN_DD=" + tbx_hidden_DISCLS_BZ_CHRG_ASSGN_DD.getValue();
        url += "&SCREN_ID=" + "ULDSTF30627.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_Save)";
        trs_Save.Post();
    }
};
